16: /** 从用户级 config.json 动态读取 TypeSafe Jev 配置。 */
17: @Slf4j
18: @Component
19: public class TypeSafeProperties {
20: 
21:     /** DEFAULT_CONFIG_PATH：ButvanAgent 用户级配置文件的默认位置。 */
22:     private static final Path DEFAULT_CONFIG_PATH = Paths.get(
23:             System.getProperty("user.home"), ".butvan-agent", "config.json");
24: 
25:     /** objectMapper：负责解析本地 JSON 配置文件的 Jackson 组件。 */
26:     private final ObjectMapper objectMapper;
27: 
28:     /** configPath：当前实例读取的配置文件位置；测试可注入临时路径。 */
29:     private final Path configPath;
30: 
31:     /**
32:      * 创建生产环境配置读取器。
33:      *
34:      * @param objectMapper Spring 统一配置的 JSON 解析器
35:      */
36:     @Autowired
37:     public TypeSafeProperties(ObjectMapper objectMapper) {
38:         this(objectMapper, DEFAULT_CONFIG_PATH);
39:     }
40: 
41:     /** 测试专用构造器，允许使用临时配置文件。 */
42:     TypeSafeProperties(ObjectMapper objectMapper, Path configPath) {
43:         this.objectMapper = objectMapper;
44:         this.configPath = configPath;
45:     }
46: 
47:     /**
48:      * 每次路由前读取最新的 TypeSafe 配置。
49:      *
50:      * @return 有效配置；文件缺失、节点缺失或读取失败时返回关闭态
51:      */
52:     public TypeSafeConfigData load() {
53:         try {
54:             if (!Files.isRegularFile(configPath)) return TypeSafeConfigData.disabled();
55: 
56:             // node：config.json 根对象中的 typesafe 配置节点。
57:             JsonNode node = objectMapper.readTree(configPath.toFile()).path("typesafe");
58:             if (node.isMissingNode() || node.isNull()) return TypeSafeConfigData.disabled();
59: 
60:             // threshold：Noul 概率达到该值时，能力组才会被选中。
61:             double threshold = node.path("threshold").asDouble(0.75);
62:             if (!Double.isFinite(threshold) || threshold < 0.0 || threshold > 1.0) {
63:                 threshold = 0.75;
64:             }
65: 
66:             String model = node.path("model").asText("jev-latest").strip();
67:             if (model.isEmpty()) model = "jev-latest";
68: 
69:             return new TypeSafeConfigData(
70:                     node.path("enabled").asBoolean(false),
71:                     ToolRoutingMode.parse(node.path("mode").asText("off")),
72:                     node.path("apiKey").asText(""),
73:                     model,
74:                     threshold
75:             );
76:         } catch (IOException | RuntimeException exception) {
77:             // exception：读取或解析本地配置时发生的异常；禁止记录配置内容。
78:             log.error("读取 TypeSafe 配置失败，Jev 路由将保持关闭：{}", configPath, exception);
79:             return TypeSafeConfigData.disabled();
80:         }
81:     }
82: 
83:     /**
84:      * 更新 Jev 总开关，同时保留 config.json 中的其他配置节点。
85:      *
86:      * @param enabled 是否开启 Jev 路由
87:      * @return 更新后的脱敏配置快照
88:      */
89:     public synchronized TypeSafeConfigData updateEnabled(boolean enabled) {
90:         TypeSafeConfigData current = load();
91:         if (enabled && !current.isConfigured()) {
92:             throw new IllegalArgumentException("Jev 尚未完成配置，请先设置有效的模式、API Key 与模型");
93:         }
94: 
95:         try {
96:             ObjectNode root = readConfigRoot();
97:             JsonNode existingNode = root.get("typesafe");
98:             ObjectNode typeSafeNode = existingNode instanceof ObjectNode objectNode
99:                     ? objectNode
100:                     : objectMapper.createObjectNode();
101:             typeSafeNode.put("enabled", enabled);
102:             root.set("typesafe", typeSafeNode);
103: 
104:             Path parent = configPath.getParent();
105:             if (parent != null) Files.createDirectories(parent);
106:             objectMapper.writerWithDefaultPrettyPrinter().writeValue(configPath.toFile(), root);
107:             return load();
108:         } catch (IOException exception) {
109:             log.error("更新 Jev 开关失败：{}", configPath, exception);
110:             throw new IllegalStateException("Jev 开关保存失败", exception);
111:         }
112:     }
113: 
114:     /** 读取配置根对象；文件不存在时返回空对象，格式异常时拒绝覆盖。 */
115:     private ObjectNode readConfigRoot() throws IOException {
116:         if (!Files.isRegularFile(configPath)) return objectMapper.createObjectNode();
117:         JsonNode root = objectMapper.readTree(configPath.toFile());
118:         if (root instanceof ObjectNode objectNode) return objectNode;
119:         throw new IOException("config.json 根节点不是对象");
120:     }
121: }

