11: /** 设置右侧的固定可视区域；滚动内容与遮罩分层，侧栏不参与遮挡或 inert。 */
12: export function SettingsMainRegion({ children, contentClassName = '' }: SettingsMainRegionProps) {
13:   const [pending, setPending] = useState<ReadonlyMap<symbol, string>>(new Map());
14:   const report = useCallback((source: symbol, label: string | null) => {
15:     setPending(current => {
16:       if (label === null ? !current.has(source) : current.get(source) === label) return current;
17:       const next = new Map(current);
18:       if (label === null) next.delete(source);
19:       else next.set(source, label);
20:       return next;
21:     });
22:   }, []);
23:   const loading = pending.size > 0;
24:   const label = Array.from(pending.values()).at(-1);
25:   return <SettingsLoadingContext.Provider value={report}>
26:     <section className={styles.region} aria-label="设置主区域">
27:       <div className={`${styles.content} ${contentClassName}`} inert={loading} aria-busy={loading}>{children}</div>
28:       <LoadingOverlay active={loading} label={label} size="large" />
29:     </section>
30:   </SettingsLoadingContext.Provider>;
31: }

