package butvan.agent.network.desktop;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;

/**
 * 跨平台 {@code agent-desktop} CLI 进程执行器。
 *
 * <p>直接通过 {@link ProcessBuilder} 参数数组传参，不经过 Shell 拼接，避免注入及 Windows PowerShell 的 {@code @ref} 参数误解析。</p>
 */
@Slf4j
@Component
public class DesktopCliRunner {

    static final int MAX_STDOUT_CHARS = 24_000;
    static final int MAX_STDERR_CHARS = 4_000;

    /** 单次 CLI 调用结果。 */
    public record CliExecutionResult(
            boolean started,
            boolean timedOut,
            int exitCode,
            String stdout,
            String stderr,
            boolean stdoutTruncated,
            String failureMessage
    ) {
        public static CliExecutionResult notFound(String message) {
            return new CliExecutionResult(false, false, -1, "", "", false, message);
        }

        public static CliExecutionResult timeout(String message) {
            return new CliExecutionResult(true, true, -1, "", "", false, message);
        }
    }

    /** 标识工具执行因会话取消而被中断。 */
    public static final class CommandCancelledException extends RuntimeException {
        public CommandCancelledException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    /** 返回归一化后的当前宿主机操作系统标识（macos / windows / linux）。 */
    public String hostOs() {
        return normalizeOs(System.getProperty("os.name", ""));
    }

    static String normalizeOs(String osName) {
        String lower = osName == null ? "" : osName.toLowerCase(Locale.ROOT);
        if (lower.contains("mac") || lower.contains("darwin")) return "macos";
        if (lower.startsWith("windows")) return "windows";
        return "linux";
    }

    /**
     * 执行一条 {@code agent-desktop} 命令。
     *
     * @param configuredCliPath 用户配置的自定义路径（可为空）
     * @param arguments         子命令与参数列表
     * @param stdinText         需要通过标准输入传递的 UTF-8 文本（可为 null）
     * @param timeout           命令最长执行时间
     */
    public CliExecutionResult execute(
            String configuredCliPath,
            List<String> arguments,
            String stdinText,
            Duration timeout
    ) {
        List<String> candidates = resolveExecutableCandidates(configuredCliPath, hostOs());
        Duration effectiveTimeout = timeout == null || timeout.isNegative() || timeout.isZero()
                ? Duration.ofSeconds(15)
                : timeout;

        IOException lastStartError = null;
        for (String executable : candidates) {
            try {
                return runSingleCandidate(executable, arguments, stdinText, effectiveTimeout);
            } catch (ProcessStartException exception) {
                lastStartError = exception.ioCause;
            }
        }

        String hint = configuredCliPath != null && !configuredCliPath.isBlank()
                ? "无法启动配置的 agent-desktop 路径（" + configuredCliPath + "），请核对文件是否存在且具备执行权限。"
                : "当前电脑未找到 agent-desktop 命令，请先安装（npm install -g agent-desktop）或在设置中指定 CLI 路径。";
        log.debug("agent-desktop 启动失败：candidates={}, error={}", candidates,
                lastStartError == null ? "none" : lastStartError.getMessage());
        return CliExecutionResult.notFound(hint);
    }

    /** 按宿主机平台构造有序可执行文件候选列表。 */
    static List<String> resolveExecutableCandidates(String configuredCliPath, String normalizedOs) {
        if (configuredCliPath != null && !configuredCliPath.isBlank()) {
            return List.of(configuredCliPath.strip());
        }
        if ("windows".equals(normalizedOs)) {
            return List.of("agent-desktop.exe", "agent-desktop.cmd", "agent-desktop");
        }
        List<String> candidates = new ArrayList<>();
        candidates.add("agent-desktop");
        if ("macos".equals(normalizedOs)) {
            addIfExecutable(candidates, "/opt/homebrew/bin/agent-desktop");
            addIfExecutable(candidates, "/usr/local/bin/agent-desktop");
        }
        String userHome = System.getProperty("user.home", "");
        if (!userHome.isBlank()) {
            addIfExecutable(candidates, Path.of(userHome, ".local", "bin", "agent-desktop").toString());
        }
        return List.copyOf(candidates);
    }

    private static void addIfExecutable(List<String> candidates, String candidatePath) {
        try {
            Path path = Path.of(candidatePath);
            if (Files.isRegularFile(path) && Files.isExecutable(path)) {
                candidates.add(candidatePath);
            }
        } catch (RuntimeException ignored) {
            // 忽略非法路径或权限查询异常
        }
    }

    private CliExecutionResult runSingleCandidate(
            String executable,
            List<String> arguments,
            String stdinText,
            Duration timeout
    ) throws ProcessStartException {
        List<String> command = new ArrayList<>(1 + (arguments == null ? 0 : arguments.size()));
        command.add(executable);
        if (arguments != null) command.addAll(arguments);

        ProcessBuilder builder = new ProcessBuilder(command);
        Process process;
        try {
            process = builder.start();
        } catch (IOException exception) {
            throw new ProcessStartException(exception);
        }

        CompletableFuture<StreamCapture> stdoutFuture = null;
        CompletableFuture<StreamCapture> stderrFuture = null;
        try {
            stdoutFuture = CompletableFuture.supplyAsync(() -> readStreamBounded(process.getInputStream(), MAX_STDOUT_CHARS));
            stderrFuture = CompletableFuture.supplyAsync(() -> readStreamBounded(process.getErrorStream(), MAX_STDERR_CHARS));

            try (OutputStream stdin = process.getOutputStream()) {
                if (stdinText != null) {
                    stdin.write(stdinText.getBytes(StandardCharsets.UTF_8));
                    stdin.flush();
                }
            } catch (IOException exception) {
                log.debug("向 agent-desktop 写入 stdin 时子进程已提前关闭：{}", exception.getMessage());
            }

            boolean finished = process.waitFor(timeout.toMillis(), TimeUnit.MILLISECONDS);
            if (!finished) {
                terminateProcessTree(process);
                cancelFuture(stdoutFuture);
                cancelFuture(stderrFuture);
                return CliExecutionResult.timeout("agent-desktop 命令执行超时（上限 " + timeout.toSeconds() + " 秒）。");
            }

            StreamCapture stdout = awaitCapture(stdoutFuture);
            StreamCapture stderr = awaitCapture(stderrFuture);
            return new CliExecutionResult(
                    true,
                    false,
                    process.exitValue(),
                    stdout.text(),
                    stderr.text(),
                    stdout.truncated(),
                    null
            );
        } catch (InterruptedException exception) {
            terminateProcessTree(process);
            cancelFuture(stdoutFuture);
            cancelFuture(stderrFuture);
            Thread.currentThread().interrupt();
            throw new CommandCancelledException("桌面操作命令已取消", exception);
        } catch (RuntimeException exception) {
            terminateProcessTree(process);
            cancelFuture(stdoutFuture);
            cancelFuture(stderrFuture);
            throw exception;
        }
    }

    private static StreamCapture readStreamBounded(InputStream inputStream, int maxChars) {
        StringBuilder builder = new StringBuilder();
        boolean truncated = false;
        char[] buffer = new char[2048];
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream, StandardCharsets.UTF_8))) {
            int read;
            while ((read = reader.read(buffer)) != -1) {
                if (builder.length() < maxChars) {
                    int remaining = maxChars - builder.length();
                    int toAppend = Math.min(read, remaining);
                    builder.append(buffer, 0, toAppend);
                    if (toAppend < read) truncated = true;
                } else {
                    truncated = true;
                }
            }
        } catch (IOException ignored) {
            // 子进程结束或被中断时正常退出读取
        }
        return new StreamCapture(builder.toString(), truncated);
    }

    private static StreamCapture awaitCapture(CompletableFuture<StreamCapture> future) throws InterruptedException {
        try {
            return future.get(3, TimeUnit.SECONDS);
        } catch (InterruptedException exception) {
            throw exception;
        } catch (Exception ignored) {
            return new StreamCapture("", false);
        }
    }

    private static void cancelFuture(CompletableFuture<?> future) {
        if (future != null) future.cancel(true);
    }

    private static void terminateProcessTree(Process process) {
        if (process == null || !process.isAlive()) return;
        process.descendants().forEach(handle -> {
            if (handle.isAlive()) handle.destroy();
        });
        process.destroy();
        if (process.isAlive()) {
            try {
                process.waitFor(500, TimeUnit.MILLISECONDS);
            } catch (InterruptedException exception) {
                Thread.currentThread().interrupt();
            }
        }
        if (process.isAlive()) {
            process.descendants().forEach(handle -> {
                if (handle.isAlive()) handle.destroyForcibly();
            });
            process.destroyForcibly();
        }
    }

    private record StreamCapture(String text, boolean truncated) {}

    private static final class ProcessStartException extends Exception {
        private final IOException ioCause;

        private ProcessStartException(IOException ioCause) {
            super(ioCause);
            this.ioCause = ioCause;
        }
    }
}

package butvan.agent.network.desktop;

/**
 * 电脑桌面操控（agent-desktop）设置与环境检测的 HTTP DTO 集合。
 */
public final class DesktopControlDtos {

    private DesktopControlDtos() {}

    /** 当前已保存配置与后端主机平台摘要。 */
    public record StatusResponse(
            boolean enabled,
            String cliPath,
            String hostOs
    ) {}

    /** 更新开关与可选自定义 CLI 路径请求体。 */
    public record UpdateRequest(
            Boolean enabled,
            String cliPath
    ) {}

    /** 有界调用 {@code agent-desktop status} 后的环境自检结果。 */
    public record CheckResponse(
            boolean available,
            String version,
            String platform,
            String accessibilityState,
            String screenRecordingState,
            String message,
            String suggestion
    ) {}
}

package butvan.agent.network.desktop;

import butvan.agent.agents.config.DesktopControlConfigData;
import butvan.agent.agents.config.DesktopControlProperties;
import butvan.agent.network.desktop.DesktopCliRunner.CliExecutionResult;
import butvan.agent.network.desktop.DesktopControlDtos.CheckResponse;
import butvan.agent.network.desktop.DesktopControlDtos.StatusResponse;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;

/**
 * 电脑桌面操控领域服务：管理 config.json 配置、环境自检及工具执行协调。
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class DesktopControlService {

    private static final Duration CHECK_TIMEOUT = Duration.ofSeconds(5);
    private static final long WRITE_LOCK_WAIT_SECONDS = 10;

    private final DesktopControlProperties properties;
    private final DesktopCliRunner cliRunner;
    private final ObjectMapper objectMapper;

    /** 单机 GUI 写操作互斥锁，防止并发点击或输入互相抢占焦点。 */
    private final Semaphore writeLock = new Semaphore(1);

    /** 读取 config.json 中当前保存的配置与后端主机系统类型（不触发外部进程）。 */
    public StatusResponse getStatus() {
        DesktopControlConfigData config = properties.load();
        return new StatusResponse(config.enabled(), config.cliPath(), cliRunner.hostOs());
    }

    /** 更新 config.json 的启用状态及可选自定义 CLI 路径。 */
    public StatusResponse updateConfig(boolean enabled, String cliPath) {
        DesktopControlConfigData updated = properties.updateConfig(enabled, cliPath);
        return new StatusResponse(updated.enabled(), updated.cliPath(), cliRunner.hostOs());
    }

    /** 执行一次有界只读环境检查（调用 {@code agent-desktop status}），返回版本与系统权限摘要。 */
    public CheckResponse checkEnvironment() {
        DesktopControlConfigData config = properties.load();
        CliExecutionResult result = cliRunner.execute(config.cliPath(), List.of("status"), null, CHECK_TIMEOUT);
        if (!result.started()) {
            return new CheckResponse(false, "", cliRunner.hostOs(), "unknown", "unknown",
                    result.failureMessage(), "请在后端所在电脑安装 agent-desktop（npm install -g agent-desktop），或在上方填写可执行文件路径。");
        }
        if (result.timedOut()) {
            return new CheckResponse(false, "", cliRunner.hostOs(), "unknown", "unknown",
                    result.failureMessage(), "请确认后端所在电脑处于已解锁的图形桌面会话中，再重试检测。");
        }

        String raw = result.stdout().strip();
        if (raw.isEmpty()) {
            String fallback = result.stderr().isBlank() ? "agent-desktop 未返回状态信息" : result.stderr().strip();
            return new CheckResponse(false, "", cliRunner.hostOs(), "unknown", "unknown",
                    fallback, "请在本机终端手动运行 agent-desktop status 排查。");
        }

        try {
            JsonNode envelope = objectMapper.readTree(raw);
            if (!envelope.path("ok").asBoolean(false)) {
                String errorMsg = envelope.path("error").path("message").asText("agent-desktop 返回错误");
                String suggestion = envelope.path("error").path("suggestion").asText("");
                return new CheckResponse(false, "", cliRunner.hostOs(), "unknown", "unknown",
                        errorMsg, suggestion);
            }

            JsonNode data = envelope.path("data");
            String version = data.path("version").asText("");
            String platform = data.path("platform").asText(cliRunner.hostOs());
            JsonNode permissions = data.path("permissions");
            String accessibilityState = permissions.path("accessibility").path("state").asText("unknown");
            String screenRecordingState = permissions.path("screen_recording").path("state").asText("unknown");
            String suggestion = permissions.path("accessibility").path("suggestion").asText("");

            String message = buildCheckSummary(platform, version, accessibilityState);
            return new CheckResponse(true, version, platform, accessibilityState, screenRecordingState, message, suggestion);
        } catch (Exception exception) {
            log.warn("解析 agent-desktop status 输出失败：{}", exception.getMessage());
            return new CheckResponse(false, "", cliRunner.hostOs(), "unknown", "unknown",
                    "无法解析 agent-desktop 返回的状态结果（退出码 " + result.exitCode() + "）。",
                    "请确认配置的 CLI 路径指向正版 agent-desktop 可执行文件。");
        }
    }

    /**
     * 供 Agent 工具调用的执行入口：实时检查 config.json 开关，按需附加会话命名空间并对写操作串行加锁。
     */
    public ToolInvocationOutcome invokeForTool(
            String sessionId,
            List<String> subcommandArgs,
            String stdinText,
            Duration timeout,
            boolean writeOperation,
            boolean attachSession
    ) {
        DesktopControlConfigData config = properties.load();
        if (!config.enabled()) {
            return ToolInvocationOutcome.error(
                    "电脑桌面操控尚未开启。请先在桌面端「设置 -> 后端连接」或手机端「设置 -> 电脑操控」中启用，"
                            + "或在 ~/.butvan-agent/config.json 中设置 desktopControl.enabled=true。");
        }

        List<String> fullArgs = new ArrayList<>(subcommandArgs.size() + 2);
        if (attachSession) {
            String normalizedSession = sanitizeSessionScope(sessionId);
            if (normalizedSession != null) {
                fullArgs.add("--session");
                fullArgs.add(normalizedSession);
            }
        }
        fullArgs.addAll(subcommandArgs);

        boolean acquired = false;
        try {
            if (writeOperation) {
                acquired = writeLock.tryAcquire(WRITE_LOCK_WAIT_SECONDS, TimeUnit.SECONDS);
                if (!acquired) {
                    return ToolInvocationOutcome.error("当前有另一项桌面操作正在执行，请稍后再试。");
                }
            }

            CliExecutionResult result = cliRunner.execute(config.cliPath(), fullArgs, stdinText, timeout);
            if (!result.started() || result.timedOut()) {
                return ToolInvocationOutcome.error(result.failureMessage());
            }

            String stdout = result.stdout().strip();
            String stderr = result.stderr().strip();
            if (stdout.isEmpty()) {
                if (result.exitCode() == 0) {
                    return ToolInvocationOutcome.success("{\"ok\":true}");
                }
                return ToolInvocationOutcome.error(stderr.isEmpty()
                        ? "agent-desktop 执行失败（退出码 " + result.exitCode() + "）。"
                        : "agent-desktop 执行失败：" + stderr);
            }

            if (result.stdoutTruncated()) {
                String notice = "\n[注意：输出已超过 " + DesktopCliRunner.MAX_STDOUT_CHARS
                        + " 字符被截断。请对 snapshot 使用 skeleton=true、interactiveOnly=true、compact=true 或指定 rootRef / app 缩小范围。]";
                return ToolInvocationOutcome.success(stdout + notice);
            }

            return ToolInvocationOutcome.success(stdout);
        } catch (InterruptedException exception) {
            Thread.currentThread().interrupt();
            return ToolInvocationOutcome.error("桌面操作已取消。");
        } catch (DesktopCliRunner.CommandCancelledException exception) {
            return ToolInvocationOutcome.error("桌面操作已取消。");
        } finally {
            if (acquired) writeLock.release();
        }
    }

    /** 将聊天 sessionId 归一化为合法的 agent-desktop session 名称（1-64 字符，仅字母/数字/-/_）。 */
    static String sanitizeSessionScope(String sessionId) {
        if (sessionId == null || sessionId.isBlank()) return null;
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < sessionId.length() && builder.length() < 48; i++) {
            char ch = sessionId.charAt(i);
            if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')
                    || (ch >= '0' && ch <= '9') || ch == '-' || ch == '_') {
                builder.append(ch);
            } else {
                builder.append('_');
            }
        }
        String sanitized = builder.toString();
        return sanitized.isEmpty() ? null : "chat-" + sanitized;
    }

    private static String buildCheckSummary(String platform, String version, String accessibilityState) {
        String versionPart = version.isBlank() ? "" : " v" + version;
        if ("granted".equalsIgnoreCase(accessibilityState)) {
            return "已检测到 agent-desktop" + versionPart + "（" + platform + "），系统无障碍权限已就绪。";
        }
        if ("denied".equalsIgnoreCase(accessibilityState)) {
            return "已检测到 agent-desktop" + versionPart + "（" + platform + "），但系统辅助功能权限未授予。";
        }
        return "已检测到 agent-desktop" + versionPart + "（" + platform + "），辅助功能权限状态：" + accessibilityState + "。";
    }

    /** 工具调用封装结果。 */
    public record ToolInvocationOutcome(boolean ok, String content) {
        public static ToolInvocationOutcome success(String content) {
            return new ToolInvocationOutcome(true, content);
        }

        public static ToolInvocationOutcome error(String message) {
            return new ToolInvocationOutcome(false, message);
        }
    }
}

package butvan.agent.network.desktop;

import butvan.agent.network.annotation.ApiLog;
import butvan.agent.network.common.Result;
import butvan.agent.network.desktop.DesktopControlDtos.CheckResponse;
import butvan.agent.network.desktop.DesktopControlDtos.StatusResponse;
import butvan.agent.network.desktop.DesktopControlDtos.UpdateRequest;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * 电脑桌面操控（agent-desktop）设置与环境自检 HTTP 适配层。
 */
@RestController
@CrossOrigin(origins = "*")
@RequestMapping("/agent/desktop-control")
@RequiredArgsConstructor
public class DesktopControlController {

    private final DesktopControlService desktopControlService;

    /** 读取当前已保存的电脑操控配置与后端主机平台。 */
    @ApiLog("查询电脑操控配置")
    @GetMapping
    public Result<StatusResponse> getStatus() {
        return Result.success(desktopControlService.getStatus());
    }

    /** 更新电脑操控启用开关与可选 CLI 路径，写入 ~/.butvan-agent/config.json。 */
    @ApiLog("更新电脑操控配置")
    @PutMapping
    public Result<StatusResponse> update(@RequestBody UpdateRequest request) {
        if (request == null || request.enabled() == null) {
            throw new IllegalArgumentException("缺少电脑操控启用状态");
        }
        return Result.success(desktopControlService.updateConfig(request.enabled(), request.cliPath()));
    }

    /** 检查后端所在电脑是否安装 agent-desktop 及系统无障碍权限状态。 */
    @ApiLog("检测电脑操控运行环境")
    @GetMapping("/check")
    public Result<CheckResponse> checkEnvironment() {
        return Result.success(desktopControlService.checkEnvironment());
    }
}

package butvan.agent.network.desktop;

import butvan.agent.agents.tool.AgentToolModule;
import butvan.agent.network.desktop.DesktopControlService.ToolInvocationOutcome;
import io.agentscope.core.agent.RuntimeContext;
import io.agentscope.core.message.ToolResultBlock;
import io.agentscope.core.tool.Tool;
import io.agentscope.core.tool.ToolParam;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Component;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * 基于 {@code agent-desktop} CLI 的电脑桌面观察与操作工具集。
 *
 * <p>只读观察工具（status/apps/snapshot/find/inspect/wait/guide）纳入自动放行白名单；
 * 所有写操作工具（action/input/window）进入统一人工审批流程，且默认使用无头语义交互（headless）。</p>
 */
@Component
@RequiredArgsConstructor
public class DesktopControlTool implements AgentToolModule {

    private static final Duration READ_TIMEOUT = Duration.ofSeconds(15);
    private static final Duration WRITE_TIMEOUT = Duration.ofSeconds(20);
    private static final int MAX_WAIT_MS = 30_000;
    private static final int MAX_DEPTH = 20;

    private static final Set<String> VALID_SURFACES = Set.of(
            "window", "focused", "menu", "menubar", "sheet", "popover", "alert",
            "desktop", "taskbar", "system-tray", "quick-settings", "notification-center",
            "toolbar", "dock", "spotlight", "menu-bar-extras", "system-tray-overflow",
            "start-menu", "action-center"
    );

    private static final Set<String> VALID_GET_PROPERTIES = Set.of(
            "text", "value", "title", "bounds", "role", "states"
    );

    private static final Set<String> VALID_IS_PROPERTIES = Set.of(
            "visible", "enabled", "checked", "focused", "expanded", "selected"
    );

    private static final Set<String> VALID_WAIT_EVENTS = Set.of(
            "window-opened", "window-closed", "app-launched", "app-terminated",
            "focus-changed", "surface-appeared", "surface-dismissed"
    );

    private static final Set<String> VALID_WAIT_PREDICATES = Set.of(
            "exists", "enabled", "visible", "actionable", "value"
    );

    private static final Set<String> VALID_SCROLL_DIRECTIONS = Set.of("up", "down", "left", "right");

    private final DesktopControlService service;

    // ==================== 只读观察工具（自动放行） ====================

    @Tool(name = "desktop_status",
            description = "检查后端所在电脑的桌面操控环境状态、操作系统平台、无障碍权限及可选显示器信息。只读。",
            readOnly = true)
    public ToolResultBlock status(
            @ToolParam(name = "request", description = "可选参数；includeDisplays=true 时返回显示器列表") StatusRequest request,
            RuntimeContext context
    ) {
        boolean includeDisplays = request != null && Boolean.TRUE.equals(request.includeDisplays());
        List<String> args = includeDisplays ? List.of("list-displays") : List.of("status");
        return toResult(service.invokeForTool(sessionId(context), args, null, READ_TIMEOUT, false, false));
    }

    @Tool(name = "desktop_apps",
