import Foundation

/// 后端 `config.json` 中 `desktopControl` 节点的配置快照。
struct DesktopControlStatus: Codable, Equatable, Sendable {
    let enabled: Bool
    let cliPath: String
    let hostOs: String

    /// 便于界面展示的宿主机操作系统名称。
    var displayHostOs: String {
        switch hostOs.lowercased() {
        case "macos":
            return "macOS"
        case "windows":
            return "Windows"
        case "linux":
            return "Linux"
        default:
            return hostOs.isEmpty ? "—" : hostOs
        }
    }
}

/// 后端调用 `agent-desktop status` 返回的运行环境自检结果。
struct DesktopControlCheckResult: Codable, Equatable, Sendable {
    let available: Bool
    let version: String
    let platform: String
    let accessibilityState: String
    let screenRecordingState: String
    let message: String
    let suggestion: String

    /// 环境是否已完全就绪（CLI 可用且无障碍权限已授予）。
    var isReady: Bool {
        available && accessibilityState.lowercased() == "granted"
    }
}

/// 电脑桌面操控配置与环境检测服务协议。
protocol DesktopControlServiceProtocol: Sendable {
    func fetchStatus() async throws -> DesktopControlStatus
    func updateConfig(enabled: Bool, cliPath: String?) async throws -> DesktopControlStatus
    func checkEnvironment() async throws -> DesktopControlCheckResult
}

import Foundation

/// 直连 `agent-backend` `/agent/desktop-control` 的电脑操控配置与环境自检服务。
final class APIDesktopControlService: DesktopControlServiceProtocol, @unchecked Sendable {
    private let client: APIClient

    init(client: APIClient) {
        self.client = client
    }

    func fetchStatus() async throws -> DesktopControlStatus {
        try await client.sendResult("/agent/desktop-control")
    }

    func updateConfig(enabled: Bool, cliPath: String?) async throws -> DesktopControlStatus {
        let payload = UpdateDesktopControlPayload(enabled: enabled, cliPath: cliPath)
        let body = try APIClient.encoder.encode(payload)
        return try await client.sendResult("/agent/desktop-control", method: "PUT", body: body)
    }

    func checkEnvironment() async throws -> DesktopControlCheckResult {
        try await client.sendResult("/agent/desktop-control/check")
    }
}

private struct UpdateDesktopControlPayload: Encodable {
    let enabled: Bool
    let cliPath: String?
}

