import SwiftUI

/// 管理电脑桌面操控配置加载、开关保存、自定义 CLI 路径与环境自检状态。
@MainActor
final class DesktopControlSettingsViewModel: ObservableObject {
    @Published private(set) var status: DesktopControlStatus?
    @Published var cliPathDraft: String = ""
    @Published private(set) var isLoading = false
    @Published private(set) var isSaving = false
    @Published private(set) var isChecking = false
    @Published private(set) var loadErrorMessage: String?
    @Published private(set) var feedbackMessage: String?
    @Published private(set) var feedbackIsError = false
    @Published private(set) var checkResult: DesktopControlCheckResult?

    private let service: any DesktopControlServiceProtocol

    init(service: any DesktopControlServiceProtocol) {
        self.service = service
    }

    var isPathDirty: Bool {
        guard let status else { return false }
        return cliPathDraft.trimmingCharacters(in: .whitespacesAndNewlines) != status.cliPath
    }

    func load() async {
        guard !isLoading else { return }
        isLoading = true
        loadErrorMessage = nil
        defer { isLoading = false }
        do {
            let loaded = try await service.fetchStatus()
            status = loaded
            cliPathDraft = loaded.cliPath
        } catch {
            loadErrorMessage = error.localizedDescription
        }
    }

    func setEnabled(_ nextEnabled: Bool) async {
        guard let current = status, !isSaving else { return }
        if current.enabled == nextEnabled { return }
        isSaving = true
        feedbackMessage = nil
        defer { isSaving = false }
        do {
            let updated = try await service.updateConfig(enabled: nextEnabled, cliPath: nil)
            status = updated
            feedbackIsError = false
            feedbackMessage = nextEnabled
                ? String(localized: "desktop_control.feedback.enabled")
                : String(localized: "desktop_control.feedback.disabled")
        } catch {
            feedbackIsError = true
            feedbackMessage = error.localizedDescription
        }
    }

    func saveCliPath() async {
        guard let current = status, !isSaving else { return }
        let trimmed = cliPathDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        isSaving = true
        feedbackMessage = nil
        defer { isSaving = false }
        do {
            let updated = try await service.updateConfig(enabled: current.enabled, cliPath: trimmed)
            status = updated
            cliPathDraft = updated.cliPath
            checkResult = nil
            feedbackIsError = false
            feedbackMessage = String(localized: "desktop_control.feedback.path_saved")
        } catch {
            feedbackIsError = true
            feedbackMessage = error.localizedDescription
        }
    }

    func checkEnvironment() async {
        guard !isChecking else { return }
        isChecking = true
        feedbackMessage = nil
        defer { isChecking = false }
        do {
            checkResult = try await service.checkEnvironment()
        } catch {
            feedbackIsError = true
            feedbackMessage = error.localizedDescription
        }
    }
}

/// 手机端「电脑操控」设置页，读写后端 `~/.butvan-agent/config.json` 中的 `desktopControl` 节点。
struct DesktopControlSettingsView: View {
    @EnvironmentObject private var environment: AppEnvironment

    var body: some View {
        DesktopControlSettingsContent(service: environment.desktopControlService)
            .background(Color(uiColor: .systemGroupedBackground).ignoresSafeArea())
            .navigationTitle("desktop_control.title")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar(.visible, for: .navigationBar)
    }
}

private struct DesktopControlSettingsContent: View {
    @StateObject private var viewModel: DesktopControlSettingsViewModel

    init(service: any DesktopControlServiceProtocol) {
        _viewModel = StateObject(wrappedValue: DesktopControlSettingsViewModel(service: service))
    }

    var body: some View {
        ScrollView {
            VStack(spacing: 24) {
                toggleGroup
                checkGroup
                cliPathGroup
                if let feedback = viewModel.feedbackMessage {
                    feedbackBanner(message: feedback, isError: viewModel.feedbackIsError)
                }
            }
            .padding(24)
        }
        .task {
            await viewModel.load()
        }
    }

    private var toggleGroup: some View {
        AppSettingsGroup(title: "desktop_control.section.control") {
            if viewModel.isLoading && viewModel.status == nil {
                HStack(spacing: 12) {
                    ProgressView()
                    Text("desktop_control.loading")
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                    Spacer(minLength: 0)
                }
                .padding(20)
            } else if let error = viewModel.loadErrorMessage, viewModel.status == nil {
                VStack(alignment: .leading, spacing: 12) {
                    Text(error)
                        .font(.subheadline)
                        .foregroundStyle(.red)
                        .fixedSize(horizontal: false, vertical: true)
                    Button("desktop_control.action.retry") {
                        Task { await viewModel.load() }
                    }
                    .font(.subheadline.weight(.medium))
                    .foregroundStyle(AppColors.primaryBlue)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(20)
            } else {
                VStack(alignment: .leading, spacing: 6) {
                    Toggle(
                        isOn: Binding(
                            get: { viewModel.status?.enabled ?? false },
                            set: { value in Task { await viewModel.setEnabled(value) } }
                        )
                    ) {
                        VStack(alignment: .leading, spacing: 4) {
                            Text("desktop_control.toggle.label")
                                .font(.body)
                                .foregroundStyle(.primary)
                            Text("desktop_control.toggle.desc")
                                .font(.caption)
                                .foregroundStyle(.secondary)
                                .fixedSize(horizontal: false, vertical: true)
                        }
                    }
                    .tint(AppColors.primaryBlue)
                    .disabled(viewModel.isSaving || viewModel.status == nil)
                }
                .padding(20)

                if let status = viewModel.status {
                    Divider().padding(.horizontal, 20)
                    AppSettingsRow(title: "desktop_control.host_os") {
                        Text(verbatim: status.displayHostOs)
                            .font(.subheadline)
                            .foregroundStyle(.secondary)
                    }
                }
            }
        }
    }

    private var checkGroup: some View {
        AppSettingsGroup(title: "desktop_control.section.environment") {
            Button {
                Task { await viewModel.checkEnvironment() }
            } label: {
                AppSettingsRow(title: "desktop_control.check.action") {
                    HStack(spacing: 8) {
                        if viewModel.isChecking {
                            ProgressView()
                                .controlSize(.small)
                        } else if let result = viewModel.checkResult {
                            statusBadge(for: result)
                        } else {
                            Image(systemName: "stethoscope")
                                .foregroundStyle(AppColors.primaryBlue)
                        }
                    }
                }
            }
            .buttonStyle(.plain)
            .disabled(viewModel.isChecking || viewModel.status == nil)

            if let result = viewModel.checkResult {
                Divider().padding(.horizontal, 20)
                VStack(alignment: .leading, spacing: 6) {
                    Text(verbatim: result.message)
                        .font(.caption)
                        .foregroundStyle(.primary)
                        .fixedSize(horizontal: false, vertical: true)
                    if !result.suggestion.isEmpty {
                        Text(verbatim: result.suggestion)
                            .font(.caption)
                            .foregroundStyle(.secondary)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(20)
            }
        }
    }

    private var cliPathGroup: some View {
        AppSettingsGroup(title: "desktop_control.section.cli_path") {
            VStack(alignment: .leading, spacing: 12) {
                Text("desktop_control.cli_path.desc")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)

                TextField("desktop_control.cli_path.placeholder", text: $viewModel.cliPathDraft)
                    .textInputAutocapitalization(.never)
                    .autocorrectionDisabled(true)
                    .font(.subheadline.monospaced())
                    .padding(.horizontal, 12)
                    .padding(.vertical, 10)
                    .background(
                        Color(uiColor: .tertiarySystemGroupedBackground),
                        in: RoundedRectangle(cornerRadius: 10, style: .continuous)
                    )
                    .disabled(viewModel.isSaving || viewModel.status == nil)

                HStack {
                    Spacer()
                    Button {
                        Task { await viewModel.saveCliPath() }
                    } label: {
                        Text("desktop_control.cli_path.save")
                            .font(.subheadline.weight(.medium))
                    }
                    .disabled(viewModel.isSaving || !viewModel.isPathDirty)
                    .foregroundStyle(
                        viewModel.isPathDirty && !viewModel.isSaving
                            ? AppColors.primaryBlue
                            : .secondary
                    )
                }
            }
            .padding(20)
        }
    }

    private func statusBadge(for result: DesktopControlCheckResult) -> some View {
        let key: LocalizedStringKey = result.isReady
            ? "desktop_control.status.ready"
            : result.available
                ? "desktop_control.status.permission_needed"
                : "desktop_control.status.unavailable"
        let color: Color = result.isReady ? .green : result.available ? .orange : .red
        return Text(key)
            .font(.caption.weight(.semibold))
            .foregroundStyle(color)
            .padding(.horizontal, 8)
