import XCTest
@testable import RecordAgent

final class DesktopControlTests: XCTestCase {

    func testDecodeStatusAndCheckResult() throws {
        let statusJson = """
        {"enabled":true,"cliPath":"C:\\\\tools\\\\agent-desktop.exe","hostOs":"windows"}
        """.data(using: .utf8)!
        let status = try APIClient.decoder.decode(DesktopControlStatus.self, from: statusJson)
        XCTAssertTrue(status.enabled)
        XCTAssertEqual(status.cliPath, "C:\\tools\\agent-desktop.exe")
        XCTAssertEqual(status.displayHostOs, "Windows")

        let checkJson = """
        {
          "available": true,
          "version": "1.3.1",
          "platform": "windows",
          "accessibilityState": "granted",
          "screenRecordingState": "granted",
          "message": "ok",
          "suggestion": ""
        }
        """.data(using: .utf8)!
        let check = try APIClient.decoder.decode(DesktopControlCheckResult.self, from: checkJson)
        XCTAssertTrue(check.isReady)
        XCTAssertEqual(check.version, "1.3.1")
    }

    @MainActor
    func testViewModelLoadToggleSavePathAndRollbackOnError() async {
        let stub = StubDesktopControlService(
            status: DesktopControlStatus(enabled: false, cliPath: "", hostOs: "macos")
        )
        let viewModel = DesktopControlSettingsViewModel(service: stub)

        await viewModel.load()
        XCTAssertEqual(viewModel.status?.enabled, false)
        XCTAssertEqual(viewModel.status?.displayHostOs, "macOS")

        await viewModel.setEnabled(true)
        XCTAssertEqual(viewModel.status?.enabled, true)
        XCTAssertFalse(viewModel.feedbackIsError)

        viewModel.cliPathDraft = "  /opt/homebrew/bin/agent-desktop  "
        XCTAssertTrue(viewModel.isPathDirty)
        await viewModel.saveCliPath()
        XCTAssertEqual(viewModel.status?.cliPath, "/opt/homebrew/bin/agent-desktop")
        XCTAssertFalse(viewModel.isPathDirty)

        await viewModel.checkEnvironment()
        XCTAssertEqual(viewModel.checkResult?.isReady, true)

        stub.shouldFailUpdate = true
        await viewModel.setEnabled(false)
        XCTAssertEqual(viewModel.status?.enabled, true)
        XCTAssertTrue(viewModel.feedbackIsError)
    }
}

private final class StubDesktopControlService: DesktopControlServiceProtocol, @unchecked Sendable {
    var status: DesktopControlStatus
    var shouldFailUpdate = false

    init(status: DesktopControlStatus) {
        self.status = status
    }

    func fetchStatus() async throws -> DesktopControlStatus {
        status
    }

    func updateConfig(enabled: Bool, cliPath: String?) async throws -> DesktopControlStatus {
        if shouldFailUpdate {
            throw NSError(domain: "DesktopControlTests", code: 500, userInfo: [
                NSLocalizedDescriptionKey: "保存失败"
            ])
        }
        status = DesktopControlStatus(
            enabled: enabled,
            cliPath: cliPath ?? status.cliPath,
            hostOs: status.hostOs
        )
        return status
    }

    func checkEnvironment() async throws -> DesktopControlCheckResult {
        DesktopControlCheckResult(
            available: true,
            version: "1.3.1",
            platform: status.hostOs,
            accessibilityState: "granted",
            screenRecordingState: "granted",
            message: "已就绪",
            suggestion: ""
        )
    }
}

